from __future__ import annotations

import math
import time
import uuid
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any, Protocol

from ..database import DatabaseBackend, dumps, loads
from ..events import RealtimeHub
from ..knowledge import AIRPORTS, Airport, airports_for


def now_iso() -> str:
    return datetime.now(UTC).isoformat()


def haversine_km(a: Airport, b: Airport) -> float:
    radius = 6371.0088
    p1, p2 = math.radians(a.latitude), math.radians(b.latitude)
    dp = math.radians(b.latitude - a.latitude)
    dl = math.radians(b.longitude - a.longitude)
    value = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * radius * math.atan2(math.sqrt(value), math.sqrt(1 - value))


@dataclass
class AgentResult:
    output: dict[str, Any]
    status: str = "completed"
    warnings: list[str] = field(default_factory=list)
    errors: list[str] = field(default_factory=list)


class Agent(Protocol):
    name: str
    task: str

    def run(self, context: dict[str, Any]) -> AgentResult: ...


class CargoAgent:
    name = "cargo_agent"
    task = "Расчёт веса, объёма и предварительная классификация груза"

    _rules = (
        ("lithium_battery", ("литий", "lithium", "battery", "батаре"), "critical"),
        ("dangerous_goods", ("опасн", "взрыв", "flammable", "dg"), "critical"),
        ("chemical", ("хим", "chemical", "кислот", "acid"), "critical"),
        ("medical", ("медиц", "лекар", "pharma", "vaccine", "вакцин"), "warning"),
        ("temperature_controlled", ("температур", "холод", "frozen", "refriger"), "warning"),
        ("weapon", ("оруж", "weapon", "боеприп", "ammo"), "critical"),
        ("dual_use", ("двойного назнач", "dual use"), "warning"),
    )

    def run(self, context: dict[str, Any]) -> AgentResult:
        cargo = context["shipment"]["cargo"]
        pieces = cargo["pieces"]
        volume_m3 = cargo["length_cm"] * cargo["width_cm"] * cargo["height_cm"] * pieces / 1_000_000
        volumetric_kg = cargo["length_cm"] * cargo["width_cm"] * cargo["height_cm"] * pieces / 6000
        chargeable_kg = max(cargo["weight_kg"], volumetric_kg)
        combined = " ".join((cargo["name"], cargo["description"], cargo.get("features", ""))).lower()
        findings = [
            {"code": code, "severity": severity, "matched": next(word for word in words if word in combined)}
            for code, words, severity in self._rules
            if any(word in combined for word in words)
        ]
        category = findings[0]["code"] if findings else "general_cargo"
        output = {
            "actual_weight_kg": round(cargo["weight_kg"], 3),
            "volume_m3": round(volume_m3, 4),
            "volumetric_weight_kg": round(volumetric_kg, 3),
            "chargeable_weight_kg": round(chargeable_kg, 3),
            "volumetric_divisor": 6000,
            "category": category,
            "restriction_findings": findings,
            "photo_analysis": "manual_review_required",
            "required_documents": ["commercial_invoice", "packing_list", "shipper_declaration"],
        }
        warnings = ["Обнаружены признаки специального или ограниченного груза"] if findings else []
        return AgentResult(output, "waiting_human" if findings else "completed", warnings)


class AirportAgent:
    name = "airport_agent"
    task = "Подбор аэропортов с учётом грузовой инфраструктуры"

    @staticmethod
    def _serialize(airport: Airport) -> dict[str, Any]:
        return {
            "icao": airport.icao, "iata": airport.iata, "name": airport.name_ru,
            "city": airport.city_ru, "country": airport.country,
            "latitude": airport.latitude, "longitude": airport.longitude,
            "cargo_terminal": airport.cargo_terminal, "customs": airport.customs,
            "warehouse": airport.warehouse, "status": airport.status, "source": airport.source,
        }

    def run(self, context: dict[str, Any]) -> AgentResult:
        shipment = context["shipment"]
        origin = airports_for(shipment["origin"]["city"], shipment["origin"]["country"])
        destination = airports_for(shipment["destination"]["city"], shipment["destination"]["country"])
        if not origin or not destination:
            return AgentResult(
                {"origin_candidates": [], "destination_candidates": []},
                "waiting_human", ["В проверяемом справочнике нет аэропортов для одной из точек"],
            )
        output = {
            "origin": self._serialize(origin[0]),
            "destination": self._serialize(destination[0]),
            "origin_alternatives": [self._serialize(x) for x in origin[1:3]],
            "destination_alternatives": [self._serialize(x) for x in destination[1:3]],
            "commercial_properties_verified": False,
        }
        return AgentResult(output, "warning", ["Коммерческие свойства аэропортов требуют подтверждения оператором"])


class CapacityAgent:
    name = "capacity_agent"
    task = "Строгая проверка свободной ёмкости по весу, объёму, маршруту и сроку действия"

    def run(self, context: dict[str, Any]) -> AgentResult:
        airport = context["results"]["airport_agent"]
        cargo = context["results"]["cargo_agent"]
        if not airport.get("origin") or not airport.get("destination"):
            return AgentResult({"matches": []}, "waiting_human", ["Невозможно искать ёмкость без аэропортов"])
        now = now_iso()
        rows = context["db"].fetch_all(
            """SELECT * FROM capacity_offers
               WHERE departure=? AND destination=? AND available_kg>=? AND available_m3>=?
                 AND valid_until>? AND cutoff_at>? ORDER BY rate_per_kg ASC""",
            (airport["origin"]["icao"], airport["destination"]["icao"], cargo["chargeable_weight_kg"], cargo["volume_m3"], now, now),
        )
        matches = []
        for row in rows:
            allowed = loads(row["allowed_categories_json"], [])
            restrictions = loads(row["restrictions_json"], [])
            if cargo["category"] not in allowed and "all" not in allowed:
                continue
            if restrictions:
                continue
            matches.append({
                "id": row["id"], "carrier": row["carrier"], "flight": row["flight"],
                "departure_at": row["departure_at"], "cutoff_at": row["cutoff_at"],
                "available_kg": row["available_kg"], "available_m3": row["available_m3"],
                "rate_per_kg": row["rate_per_kg"], "minimum_charge": row["minimum_charge"],
                "currency": row["currency"], "confidence": row["confidence"],
                "source_reference": row["source_reference"], "valid_until": row["valid_until"],
            })
        if not matches:
            return AgentResult(
                {"matches": [], "required_kg": cargo["chargeable_weight_kg"], "required_m3": cargo["volume_m3"]},
                "waiting_human", ["Подтверждённая свободная ёмкость не найдена; требуется RFQ или ручной оффер"],
            )
        return AgentResult({"matches": matches[:5], "selected": matches[0]})


class RouteAgent:
    name = "route_agent"
    task = "Построение прямого и транзитных вариантов маршрута"

    def run(self, context: dict[str, Any]) -> AgentResult:
        airport_result = context["results"]["airport_agent"]
        if not airport_result.get("origin") or not airport_result.get("destination"):
            return AgentResult({"routes": []}, "waiting_human", ["Маршрут не построен без аэропортов"])
        by_icao = {a.icao: a for a in AIRPORTS}
        origin = by_icao[airport_result["origin"]["icao"]]
        destination = by_icao[airport_result["destination"]["icao"]]
        direct_distance = round(haversine_km(origin, destination))
        capacity = context["results"]["capacity_agent"].get("selected")
        routes = [{
            "id": str(uuid.uuid4()), "label": "recommended", "kind": "direct",
            "nodes": [origin.icao, destination.icao], "distance_km": direct_distance,
            "estimated_hours": round(direct_distance / 720 + 3, 1),
            "transfers": 0, "capacity_offer_id": capacity["id"] if capacity else None,
            "confidence": "partner_confirmed" if capacity and capacity["confidence"] == "partner_confirmed" else "planning_estimate",
            "operational_warning": "Не является Operational Flight Plan; разрешения и расписание требуют проверки",
        }]
        for hub_code in ("UTDD", "UTTT", "ZWWW"):
            hub = by_icao[hub_code]
            if hub.icao in (origin.icao, destination.icao):
                continue
            distance = round(haversine_km(origin, hub) + haversine_km(hub, destination))
            routes.append({
                "id": str(uuid.uuid4()), "label": "alternative", "kind": "via_hub",
                "nodes": [origin.icao, hub.icao, destination.icao], "distance_km": distance,
                "estimated_hours": round(distance / 700 + 9, 1), "transfers": 1,
                "capacity_offer_id": None, "confidence": "planning_estimate",
                "operational_warning": "Ёмкость обоих плеч, трансфер и разрешения не подтверждены",
            })
        return AgentResult({"routes": routes[:4], "selected": routes[0]}, "warning", ["Маршруты являются коммерческими вариантами, не планом полёта"])


class PricingAgent:
    name = "pricing_agent"
    task = "Формирование проверяемой основы цены без смешивания валют"

    def run(self, context: dict[str, Any]) -> AgentResult:
        cargo = context["results"]["cargo_agent"]
        offer = context["results"]["capacity_agent"].get("selected")
        if not offer:
            return AgentResult(
                {"price_available": False, "required_action": "operator_rfq", "customer_price": None},
                "waiting_human", ["Цена не рассчитана: нет подтверждённой ставки перевозчика"],
            )
        linehaul = max(offer["minimum_charge"], offer["rate_per_kg"] * cargo["chargeable_weight_kg"])
        return AgentResult({
            "price_available": False,
            "carrier_linehaul": round(linehaul, 2),
            "currency": offer["currency"],
            "rate_source": offer["source_reference"],
            "rate_confidence": offer["confidence"],
            "pending_costs": ["ground_pickup", "origin_handling", "warehouse", "customs", "destination_handling", "last_mile", "insurance", "risk_reserve", "skyseal_margin"],
            "required_action": "operator_complete_and_send_quote",
            "customer_price": None,
        }, "waiting_human", ["Финальная цена требует внесения расходов и подтверждения оператором"])


class ComplianceAgent:
    name = "compliance_agent"
    task = "Предварительная проверка ограничений и формирование контрольных ворот"

    def run(self, context: dict[str, Any]) -> AgentResult:
        shipment = context["shipment"]
        cargo = context["results"]["cargo_agent"]
        gates = [
            {"code": "shipper_kyc", "state": "pending", "label": "Проверка отправителя и получателя"},
            {"code": "cargo_docs", "state": "pending", "label": "Проверка состава и документов груза"},
            {"code": "export_controls", "state": "pending", "label": "Экспортные ограничения и товары двойного назначения"},
            {"code": "route_permissions", "state": "pending", "label": "Разрешения маршрута и аэропортов"},
            {"code": "sanctions_screening", "state": "pending", "label": "Санкционная проверка сторон"},
        ]
        if shipment["destination"]["country"] == "AF" or shipment["origin"]["country"] == "AF":
            gates.extend([
                {"code": "war_risk", "state": "pending", "label": "Страхование военных рисков"},
                {"code": "afghanistan_permits", "state": "pending", "label": "Разрешения и обработка в Афганистане"},
            ])
        return AgentResult({
            "decision": "human_approval_required", "gates": gates,
            "cargo_findings": cargo["restriction_findings"],
            "legal_notice": "Это предварительные флаги, а не юридическое заключение и не разрешение к перевозке",
        }, "waiting_human", ["Обязательное подтверждение compliance-специалиста"])


class BackhaulAgent:
    name = "backhaul_agent"
    task = "Поиск обратной ёмкости для экономики полного оборотного цикла"

    def run(self, context: dict[str, Any]) -> AgentResult:
        airport = context["results"]["airport_agent"]
        if not airport.get("origin") or not airport.get("destination"):
            return AgentResult({"matches": []}, "warning", ["Обратное плечо невозможно определить"])
        now = now_iso()
        rows = context["db"].fetch_all(
            "SELECT * FROM capacity_offers WHERE departure=? AND destination=? AND valid_until>? AND cutoff_at>? ORDER BY rate_per_kg",
            (airport["destination"]["icao"], airport["origin"]["icao"], now, now),
        )
        matches = [{"id": r["id"], "carrier": r["carrier"], "flight": r["flight"], "available_kg": r["available_kg"], "available_m3": r["available_m3"], "currency": r["currency"], "confidence": r["confidence"]} for r in rows[:5]]
        return AgentResult({"matches": matches, "full_cycle_profit": None, "requires_confirmed_costs": True}, "warning" if not matches else "completed", [] if matches else ["Подтверждённое обратное плечо не найдено"])


class DocumentAgent:
    name = "document_agent"
    task = "Формирование версионированного пакета черновиков и чек-листа"

    def run(self, context: dict[str, Any]) -> AgentResult:
        shipment = context["shipment"]
        return AgentResult({
            "documents": [
                {"type": "cargo_passport", "status": "draft"},
                {"type": "commercial_offer", "status": "blocked_until_operator_quote"},
                {"type": "awb_data", "status": "draft_requires_carrier"},
                {"type": "shipping_checklist", "status": "draft"},
            ],
            "shipment_reference": shipment["reference"],
            "notice": "Документы являются черновиками и требуют подтверждения уполномоченного лица",
        })


class ConfidenceAgent:
    name = "confidence_agent"
    task = "Оценка достоверности данных и запрет выдачи неподтверждённого результата"

    def run(self, context: dict[str, Any]) -> AgentResult:
        capacity = context["results"]["capacity_agent"]
        score = 35
        missing = ["airport_commercial_terms", "compliance_approval", "complete_costs"]
        if capacity.get("selected"):
            score += 25
        cargo = context["results"]["cargo_agent"]
        if not cargo["restriction_findings"]:
            score += 10
        level = "operator_action_required" if score < 80 else "ready_for_operator_approval"
        return AgentResult({"score": min(score, 100), "level": level, "missing_confirmations": missing}, "waiting_human")


AGENTS: tuple[Agent, ...] = (
    CargoAgent(), AirportAgent(), CapacityAgent(), RouteAgent(), PricingAgent(),
    ComplianceAgent(), BackhaulAgent(), DocumentAgent(), ConfidenceAgent(),
)


class DirectorOrchestrator:
    def __init__(self, db: DatabaseBackend, hub: RealtimeHub):
        self.db = db
        self.hub = hub

    async def process(self, shipment_id: str) -> None:
        row = self.db.fetch_one("SELECT * FROM shipments WHERE id=?", (shipment_id,))
        if not row:
            return
        shipment = hydrate_shipment(row)
        self.db.execute("UPDATE shipments SET status='analyzing', updated_at=? WHERE id=?", (now_iso(), shipment_id))
        await self.hub.publish("shipment.updated", {"id": shipment_id, "status": "analyzing"}, shipment_id)
        context: dict[str, Any] = {"shipment": shipment, "results": {}, "db": self.db}
        for agent in AGENTS:
            run_id = str(uuid.uuid4())
            started = now_iso()
            self.db.execute(
                """INSERT INTO agent_runs(
                     id,shipment_id,agent,task,status,input_json,output_json,warnings_json,errors_json,
                     started_at,completed_at,duration_ms
                   ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    run_id, shipment_id, agent.name, agent.task, "running",
                    dumps({"shipment_id": shipment_id}), dumps({}), dumps([]), dumps([]), started, None, None,
                ),
            )
            await self.hub.publish("agent.started", {"id": run_id, "agent": agent.name, "task": agent.task, "status": "running"}, shipment_id)
            tick = time.perf_counter()
            try:
                result = agent.run(context)
            except Exception as exc:
                result = AgentResult({}, "failed", [], [str(exc)])
            duration = int((time.perf_counter() - tick) * 1000)
            context["results"][agent.name] = result.output
            self.db.execute(
                "UPDATE agent_runs SET status=?, output_json=?, warnings_json=?, errors_json=?, completed_at=?, duration_ms=? WHERE id=?",
                (result.status, dumps(result.output), dumps(result.warnings), dumps(result.errors), now_iso(), duration, run_id),
            )
            await self.hub.publish("agent.completed", {"id": run_id, "agent": agent.name, "task": agent.task, "status": result.status, "warnings": result.warnings, "output": result.output}, shipment_id)

        cargo = context["results"]["cargo_agent"]
        existing_passport = self.db.fetch_one("SELECT id FROM cargo_passports WHERE shipment_id=?", (shipment_id,))
        passport_id = existing_passport["id"] if existing_passport else str(uuid.uuid4())
        passport = {
            "shipment_id": shipment_id, "reference": shipment["reference"], "version": 1,
            "cargo": cargo, "photos": {"product": shipment["product_photo_ids"], "packaging": shipment["packaging_photo_ids"]},
            "vision_status": "manual_review_required", "change_history": [{"version": 1, "created_at": now_iso(), "actor": "system"}],
        }
        self.db.execute(
            """INSERT INTO cargo_passports(id,shipment_id,version,data_json,confidence,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?)
               ON CONFLICT(id) DO UPDATE SET version=excluded.version,data_json=excluded.data_json,
                 confidence=excluded.confidence,updated_at=excluded.updated_at""",
            (passport_id, shipment_id, 1, dumps(passport), "operator_action_required", now_iso(), now_iso()),
        )
        for route in context["results"]["route_agent"].get("routes", []):
            self.db.execute(
                """INSERT INTO routes(id,shipment_id,label,data_json,confidence,created_at) VALUES(?,?,?,?,?,?)
                   ON CONFLICT(id) DO UPDATE SET label=excluded.label,data_json=excluded.data_json,
                     confidence=excluded.confidence,created_at=excluded.created_at""",
                (route["id"], shipment_id, route["label"], dumps(route), route["confidence"], now_iso()),
            )
        selected_route = context["results"]["route_agent"].get("selected", {}).get("id")
        missing_capacity = not context["results"]["capacity_agent"].get("selected")
        final_status = "needs_review" if missing_capacity else "quote_draft"
        if missing_capacity:
            self.db.execute(
                "INSERT INTO exceptions(id,shipment_id,code,severity,title,detail,resolved_at,created_at) VALUES(?,?,?,?,?,?,?,?)",
                (str(uuid.uuid4()), shipment_id, "CAPACITY_MISSING", "high", "Нет подтверждённой ёмкости", "Отправьте RFQ перевозчику или внесите подтверждённый оффер", None, now_iso()),
            )
        self.db.execute(
            "UPDATE shipments SET status=?, cargo_passport_id=?, selected_route_id=?, updated_at=? WHERE id=?",
            (final_status, passport_id, selected_route, now_iso(), shipment_id),
        )
        self.db.execute(
            "INSERT INTO status_events(id,shipment_id,from_status,to_status,actor_role,note,created_at) VALUES(?,?,?,?,?,?,?)",
            (str(uuid.uuid4()), shipment_id, "analyzing", final_status, "system", "Работа агентов завершена; требуется решение оператора", now_iso()),
        )
        await self.hub.publish("shipment.updated", {"id": shipment_id, "status": final_status, "confidence": context["results"]["confidence_agent"]}, shipment_id)


def hydrate_shipment(row: dict[str, Any]) -> dict[str, Any]:
    return {
        **{key: value for key, value in row.items() if not key.endswith("_json") and key != "tracking_token_hash"},
        "origin": loads(row["origin_json"], {}), "destination": loads(row["destination_json"], {}),
        "cargo": loads(row["cargo_json"], {}),
        "product_photo_ids": loads(row["product_photo_ids_json"], []),
        "packaging_photo_ids": loads(row["packaging_photo_ids_json"], []),
    }

