from __future__ import annotations

import hmac
from dataclasses import dataclass
from typing import Any

import httpx
from fastapi import HTTPException

from .config import Settings


@dataclass(frozen=True)
class OperatorIdentity:
    subject: str
    role: str
    provider: str
    email: str = ""


class LocalOperatorAuth:
    def __init__(self, password: str):
        self.password = password

    def authenticate(self, email: str, password: str) -> OperatorIdentity:
        if not hmac.compare_digest(password, self.password):
            raise HTTPException(status_code=401, detail="Неверный пароль")
        return OperatorIdentity(subject="local-operator", role="operator", provider="local", email=email)


class SupabaseOperatorAuth:
    def __init__(self, url: str, publishable_key: str, transport: httpx.BaseTransport | None = None):
        self.url = url.rstrip("/")
        self.publishable_key = publishable_key
        self.transport = transport

    def authenticate(self, email: str, password: str) -> OperatorIdentity:
        if not email:
            raise HTTPException(status_code=422, detail="Для облачного входа укажите email")
        try:
            with httpx.Client(timeout=20, transport=self.transport) as client:
                response = client.post(
                    f"{self.url}/auth/v1/token?grant_type=password",
                    headers={"apikey": self.publishable_key, "Content-Type": "application/json"},
                    json={"email": email, "password": password},
                )
        except httpx.HTTPError as exc:
            raise HTTPException(status_code=503, detail="Сервис авторизации временно недоступен") from exc
        if response.status_code != 200:
            raise HTTPException(status_code=401, detail="Неверный email или пароль")
        user: dict[str, Any] = response.json().get("user") or {}
        role = (user.get("app_metadata") or {}).get("role", "")
        if role not in {"operator", "admin"}:
            raise HTTPException(status_code=403, detail="У пользователя нет роли диспетчера")
        return OperatorIdentity(
            subject=str(user.get("id", "")),
            role=role,
            provider="supabase",
            email=str(user.get("email", email)),
        )


OperatorAuth = LocalOperatorAuth | SupabaseOperatorAuth


def create_operator_auth(config: Settings) -> OperatorAuth:
    if config.backend("auth") == "supabase":
        return SupabaseOperatorAuth(config.supabase_url, config.supabase_publishable_key)
    return LocalOperatorAuth(config.operator_password)

