from __future__ import annotations

import os
import secrets
from dataclasses import dataclass
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent


@dataclass(frozen=True)
class Settings:
    root: Path = ROOT
    data_dir: Path = ROOT / "data"
    uploads_dir: Path = ROOT / "uploads"
    database_path: Path = ROOT / "data" / "skyseal.db"
    host: str = os.getenv("SKYSEAL_HOST", "0.0.0.0")
    port: int = int(os.getenv("SKYSEAL_PORT", "8787"))
    runtime_profile: str = os.getenv("SKYSEAL_RUNTIME_PROFILE", "local").lower()
    database_backend: str = os.getenv("SKYSEAL_DATABASE_BACKEND", "").lower()
    database_url: str = os.getenv("SKYSEAL_DATABASE_URL", "")
    storage_backend: str = os.getenv("SKYSEAL_STORAGE_BACKEND", "").lower()
    auth_backend: str = os.getenv("SKYSEAL_AUTH_BACKEND", "").lower()
    supabase_url: str = os.getenv("SKYSEAL_SUPABASE_URL", "")
    supabase_publishable_key: str = os.getenv("SKYSEAL_SUPABASE_PUBLISHABLE_KEY", "")
    supabase_secret_key: str = os.getenv("SKYSEAL_SUPABASE_SECRET_KEY", "")
    operator_password: str = os.getenv("SKYSEAL_OPERATOR_PASSWORD", "skyseal-demo-2026")
    demo_mode: bool = os.getenv("SKYSEAL_DEMO_MODE", "1") == "1"
    secure_cookies: bool = os.getenv("SKYSEAL_SECURE_COOKIES", "0") == "1"
    max_image_bytes: int = 8 * 1024 * 1024

    def backend(self, component: str) -> str:
        configured = {
            "database": self.database_backend,
            "storage": self.storage_backend,
            "auth": self.auth_backend,
        }[component]
        if configured:
            return configured
        if self.runtime_profile == "cloud":
            return {"database": "postgres", "storage": "supabase", "auth": "supabase"}[component]
        if self.runtime_profile == "hybrid":
            return {"database": "postgres", "storage": "supabase", "auth": "local"}[component]
        return {"database": "sqlite", "storage": "local", "auth": "local"}[component]

    def validate(self) -> None:
        if self.runtime_profile not in {"local", "cloud", "hybrid"}:
            raise RuntimeError("SKYSEAL_RUNTIME_PROFILE должен быть local, hybrid или cloud")
        allowed = {"database": {"sqlite", "postgres"}, "storage": {"local", "supabase"}, "auth": {"local", "supabase"}}
        for component, values in allowed.items():
            if self.backend(component) not in values:
                raise RuntimeError(f"Некорректный backend {component}: {self.backend(component)}")
        if self.backend("database") == "postgres" and not self.database_url:
            raise RuntimeError("Для PostgreSQL задайте SKYSEAL_DATABASE_URL")
        if self.backend("storage") == "supabase" and not (self.supabase_url and self.supabase_secret_key):
            raise RuntimeError("Для Supabase Storage задайте SKYSEAL_SUPABASE_URL и SKYSEAL_SUPABASE_SECRET_KEY")
        if self.backend("auth") == "supabase" and not (self.supabase_url and self.supabase_publishable_key):
            raise RuntimeError("Для Supabase Auth задайте SKYSEAL_SUPABASE_URL и SKYSEAL_SUPABASE_PUBLISHABLE_KEY")
        if self.runtime_profile == "cloud":
            if not self.secure_cookies:
                raise RuntimeError("В cloud-профиле включите SKYSEAL_SECURE_COOKIES=1 и используйте HTTPS")
            if not os.getenv("SKYSEAL_SESSION_SECRET", "").strip():
                raise RuntimeError("В cloud-профиле задайте общий SKYSEAL_SESSION_SECRET")

    def ensure_directories(self) -> None:
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.uploads_dir.mkdir(parents=True, exist_ok=True)

    def session_secret(self) -> bytes:
        configured = os.getenv("SKYSEAL_SESSION_SECRET", "").strip()
        if configured:
            return configured.encode("utf-8")
        self.ensure_directories()
        secret_path = self.data_dir / ".session-secret"
        if not secret_path.exists():
            secret_path.write_text(secrets.token_urlsafe(48), encoding="utf-8")
        return secret_path.read_text(encoding="utf-8").strip().encode("utf-8")


