class Database:
    def __init__(self, path: Path):
        self.path = path
        self._write_lock = threading.RLock()

    def connect(self) -> sqlite3.Connection:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        conn = sqlite3.connect(self.path, timeout=20, check_same_thread=False)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA busy_timeout = 5000")
        return conn

    def initialize(self) -> None:
        with self.connect() as conn:
            conn.executescript(SCHEMA)
            conn.execute("INSERT OR IGNORE INTO schema_version(version, applied_at) VALUES(1, datetime('now'))")
            conn.execute("INSERT OR IGNORE INTO schema_version(version, applied_at) VALUES(2, datetime('now'))")

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        with self._write_lock:
            conn = self.connect()
            try:
                conn.execute("BEGIN IMMEDIATE")
                yield conn
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def execute(self, sql: str, params: tuple[Any, ...] = ()) -> None:
        with self.transaction() as conn:
            conn.execute(sql, params)

    def fetch_one(self, sql: str, params: tuple[Any, ...] = ()) -> dict[str, Any] | None:
        with self.connect() as conn:
            row = conn.execute(sql, params).fetchone()
            return dict(row) if row else None

    def fetch_all(self, sql: str, params: tuple[Any, ...] = ()) -> list[dict[str, Any]]:
        with self.connect() as conn:
            return [dict(row) for row in conn.execute(sql, params).fetchall()]

    def close(self) -> None:
        return None


class PostgresConnection:
    def __init__(self, connection: Any):
        self.connection = connection

    def execute(self, sql: str, params: tuple[Any, ...] = ()) -> Any:
        return PostgresCursor(self.connection.execute(_postgres_sql(sql), _postgres_params(params)))


class PostgresCursor:
    def __init__(self, cursor: Any):
        self.cursor = cursor

    def fetchone(self) -> dict[str, Any] | None:
        row = self.cursor.fetchone()
        return _normalize_row(row) if row else None

    def fetchall(self) -> list[dict[str, Any]]:
        return [_normalize_row(row) for row in self.cursor.fetchall()]


class PostgresDatabase:
    """PostgreSQL adapter preserving the small database API used by SkySeal Core."""

    def __init__(self, database_url: str):
        try:
            from psycopg.rows import dict_row
            from psycopg_pool import ConnectionPool
        except ImportError as exc:  # pragma: no cover - only possible with an incomplete installation
            raise RuntimeError("Установите зависимости из requirements.txt для режима PostgreSQL") from exc
        self.pool = ConnectionPool(
            conninfo=database_url,
            min_size=1,
            max_size=8,
            kwargs={"row_factory": dict_row, "options": "-c search_path=skyseal,public"},
            open=False,
            timeout=15,
        )

    def initialize(self) -> None:
        self.pool.open(wait=True)
        row = self.fetch_one("SELECT current_database() database_name, 1 ready")
        if not row or row["ready"] != 1:
            raise RuntimeError("PostgreSQL не прошёл проверку готовности")

    @contextmanager
    def transaction(self) -> Iterator[PostgresConnection]:
        with self.pool.connection() as conn:
            with conn.transaction():
                yield PostgresConnection(conn)

    def execute(self, sql: str, params: tuple[Any, ...] = ()) -> None:
        with self.transaction() as conn:
            conn.execute(sql, params)

    def fetch_one(self, sql: str, params: tuple[Any, ...] = ()) -> dict[str, Any] | None:
        with self.pool.connection() as conn:
            row = conn.execute(_postgres_sql(sql), _postgres_params(params)).fetchone()
            return _normalize_row(row) if row else None

    def fetch_all(self, sql: str, params: tuple[Any, ...] = ()) -> list[dict[str, Any]]:
        with self.pool.connection() as conn:
            return [_normalize_row(row) for row in conn.execute(_postgres_sql(sql), _postgres_params(params)).fetchall()]

    def close(self) -> None:
        self.pool.close()


DatabaseBackend = Database | PostgresDatabase


def create_database(config: Settings) -> DatabaseBackend:
    if config.backend("database") == "postgres":
        return PostgresDatabase(config.database_url)
    return Database(config.database_path)


class JsonText(str):
    """Marks serialized JSON so psycopg can bind it as jsonb without guessing from ordinary strings."""


def _postgres_sql(sql: str) -> str:
    return sql.replace("?", "%s")


def _postgres_params(params: tuple[Any, ...]) -> tuple[Any, ...]:
    try:
        from psycopg.types.json import Jsonb
    except ImportError:  # pragma: no cover - local SQLite mode does not require psycopg
        return params
    return tuple(Jsonb(json.loads(value)) if isinstance(value, JsonText) else value for value in params)


def dumps(value: Any) -> JsonText:
    return JsonText(json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str))


def loads(value: str | dict[str, Any] | list[Any] | None, fallback: Any = None) -> Any:
    if value is None:
        return fallback
    if isinstance(value, (dict, list)):
        return value
    return json.loads(value)


def _normalize_value(value: Any) -> Any:
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, UUID):
        return str(value)
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, dict):
        return {key: _normalize_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_normalize_value(item) for item in value]
    return value


def _normalize_row(row: Any) -> dict[str, Any]:
    return {key: _normalize_value(value) for key, value in dict(row).items()}

