        shipment = conn.execute("SELECT * FROM shipments WHERE id=?", (shipment_id,)).fetchone()
        if not shipment:
            raise HTTPException(status_code=404, detail="Заявка не найдена")
        if shipment["status"] not in {"needs_review", "quote_draft", "quote_sent"}:
            raise HTTPException(status_code=409, detail="В текущем статусе предложение отправить нельзя")
        latest = conn.execute("SELECT COALESCE(MAX(version),0) version FROM quote_bundles WHERE shipment_id=?", (shipment_id,)).fetchone()
        conn.execute("UPDATE quote_bundles SET status='superseded' WHERE shipment_id=? AND status='sent'", (shipment_id,))
        conn.execute(
            """INSERT INTO quote_bundles(
                 id,shipment_id,version,status,expires_at,note,approved_by,selected_option_id,created_at,accepted_at
               ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
            (bundle_id, shipment_id, int(latest["version"]) + 1, "sent", expires_at.isoformat(), payload.note, operator["sub"], None, created_at, None),
        )
        event_options = []
        for option in payload.options:
            option_id = str(uuid.uuid4())
            conn.execute(
                """INSERT INTO quote_options(
                     id,bundle_id,tariff,title,amount,currency,eta_min_hours,eta_max_hours,route_summary,
                     conditions,source_reference,confidence,recommended,created_at
                   ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    option_id, bundle_id, option.tariff, option.title, option.amount, option.currency,
                    option.eta_min_hours, option.eta_max_hours, option.route_summary, option.conditions,
                    option.source_reference, option.source_confidence, option.recommended, created_at,
                ),
            )
            event_options.append({"id": option_id, "tariff": option.tariff, "amount": option.amount, "currency": option.currency})
        conn.execute("UPDATE shipments SET quote_id=?, status='quote_sent', updated_at=? WHERE id=?", (bundle_id, created_at, shipment_id))
        conn.execute(
            "INSERT INTO status_events(id,shipment_id,from_status,to_status,actor_role,note,created_at) VALUES(?,?,?,?,?,?,?)",
            (str(uuid.uuid4()), shipment_id, shipment["status"], "quote_sent", "operator", f"Оператор отправил {len(payload.options)} варианта перевозки", created_at),
        )
        conn.execute(
            "INSERT INTO audit_log(id,actor_role,action,entity_type,entity_id,data_json,created_at) VALUES(?,?,?,?,?,?,?)",
            (str(uuid.uuid4()), "operator", "quote.bundle_sent", "quote_bundle", bundle_id, dumps({"shipment_id": shipment_id, "options": event_options}), created_at),
        )
    await hub.publish("quote.sent", {"shipment_id": shipment_id, "status": "quote_sent", "bundle_id": bundle_id, "options": event_options, "expires_at": expires_at.isoformat()}, shipment_id)
    return get_shipment_detail(db, shipment_id)


def parse_datetime(value: str | datetime) -> datetime:
    if isinstance(value, datetime):
        parsed = value
        if parsed.tzinfo is None:
            raise HTTPException(status_code=422, detail="Укажите часовой пояс даты и времени")
        return parsed.astimezone(UTC)
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise HTTPException(status_code=422, detail="Некорректная дата и время") from exc
    if parsed.tzinfo is None:
        raise HTTPException(status_code=422, detail="Укажите часовой пояс даты и времени")
    return parsed.astimezone(UTC)


