def enforce_rate(request: Request, bucket: str, limit: int, window_seconds: int) -> None:
    host = request.client.host if request.client else "unknown"
    key = f"{bucket}:{host}"
    now = time.monotonic()
    values = rate_windows[key]
    while values and values[0] <= now - window_seconds:
        values.popleft()
    if len(values) >= limit:
        raise HTTPException(status_code=429, detail="Слишком много запросов. Повторите позже")
    values.append(now)


