from __future__ import annotations

import base64
import hashlib
import hmac
import json
import secrets
import time
from typing import Any

from fastapi import HTTPException, Request, WebSocket, status

from .config import settings

COOKIE_NAME = "skyseal_operator"


def _b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _unb64(value: str) -> bytes:
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def sign_session(
    subject: str = "local-operator",
    role: str = "operator",
    provider: str = "local",
    email: str = "",
    lifetime_seconds: int = 12 * 3600,
) -> str:
    payload = {
        "sub": subject,
        "role": role,
        "provider": provider,
        "email": email,
        "exp": int(time.time()) + lifetime_seconds,
        "nonce": secrets.token_hex(8),
    }
    body = _b64(json.dumps(payload, separators=(",", ":")).encode("utf-8"))
    signature = _b64(hmac.new(settings.session_secret(), body.encode("ascii"), hashlib.sha256).digest())
    return f"{body}.{signature}"


def verify_session(
    token: str | None,
    allowed_roles: tuple[str, ...] = ("operator", "admin"),
) -> dict[str, Any] | None:
    if not token or "." not in token:
        return None
    body, supplied = token.split(".", 1)
    expected = _b64(hmac.new(settings.session_secret(), body.encode("ascii"), hashlib.sha256).digest())
    if not hmac.compare_digest(supplied, expected):
        return None
    try:
        payload = json.loads(_unb64(body))
    except (ValueError, json.JSONDecodeError):
        return None
    if payload.get("role") not in allowed_roles or int(payload.get("exp", 0)) < int(time.time()):
        return None
    return payload


def require_operator(request: Request) -> dict[str, Any]:
    session = verify_session(request.cookies.get(COOKIE_NAME))
    if session is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Требуется вход диспетчера")
    return session


def operator_from_websocket(websocket: WebSocket) -> bool:
    return verify_session(websocket.cookies.get(COOKIE_NAME)) is not None


def new_tracking_token() -> str:
    return secrets.token_urlsafe(32)


def token_digest(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def verify_tracking_token(token: str, digest: str) -> bool:
    return hmac.compare_digest(token_digest(token), digest)

