from __future__ import annotations

import base64
import binascii
import hashlib
import secrets
import uuid
from datetime import UTC, datetime
from typing import Any

import httpx
from fastapi import HTTPException, status

from .config import settings
from .database import DatabaseBackend, dumps, loads
from .models import CapacityOfferCreate, ImageUpload, ShipmentCreate
from .security import new_tracking_token, token_digest, verify_tracking_token
from .storage import EvidenceObject, EvidenceStorage


def now_iso() -> str:
    return datetime.now(UTC).isoformat()


def _reference(conn: Any) -> str:
    prefix = datetime.now(UTC).strftime("SS-%Y%m%d")
    row = conn.execute("SELECT COUNT(*) AS count FROM shipments WHERE reference LIKE ?", (f"{prefix}-%",)).fetchone()
    return f"{prefix}-{int(row['count']) + 1:04d}"


def save_image(db: DatabaseBackend, storage: EvidenceStorage, payload: ImageUpload) -> dict[str, Any]:
    raw_value = payload.data_base64.split(",", 1)[-1]
    try:
        content = base64.b64decode(raw_value, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise HTTPException(status_code=400, detail="Повреждённые данные изображения") from exc
    if len(content) > settings.max_image_bytes:
        raise HTTPException(status_code=413, detail="Фотография превышает 8 МБ")
    signatures = {
        "image/jpeg": (b"\xff\xd8\xff", ".jpg"),
        "image/png": (b"\x89PNG\r\n\x1a\n", ".png"),
        "image/webp": (b"RIFF", ".webp"),
    }
    signature, extension = signatures[payload.mime_type]
    valid = content.startswith(signature)
    if payload.mime_type == "image/webp":
        valid = valid and len(content) > 12 and content[8:12] == b"WEBP"
    if not valid:
        raise HTTPException(status_code=400, detail="Фактический формат файла не совпадает с заявленным")
    image_id = str(uuid.uuid4())
    storage_name = f"unassigned/{image_id}{extension}"
    sha = hashlib.sha256(content).hexdigest()
    try:
        storage.put(storage_name, content, payload.mime_type)
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=503, detail="Хранилище фотографий временно недоступно") from exc
    try:
        db.execute(
            "INSERT INTO photos(id, storage_path, original_name, mime_type, sha256, size_bytes, created_at) VALUES(?,?,?,?,?,?,?)",
            (image_id, storage_name, payload.filename, payload.mime_type, sha, len(content), now_iso()),
        )
    except Exception:
        try:
            storage.delete(storage_name)
        except Exception:
            pass
        raise
    return {"id": image_id, "mime_type": payload.mime_type, "size_bytes": len(content), "sha256": sha}


def create_shipment(db: DatabaseBackend, payload: ShipmentCreate) -> tuple[dict[str, Any], str]:
    token = new_tracking_token()
    shipment_id = str(uuid.uuid4())
    now = now_iso()
    all_photo_ids = payload.product_photo_ids + payload.packaging_photo_ids
    if len(set(all_photo_ids)) != len(all_photo_ids):
        raise HTTPException(status_code=400, detail="Фотографии не должны повторяться")
    with db.transaction() as conn:
        placeholders = ",".join("?" for _ in all_photo_ids)
        rows = conn.execute(f"SELECT id, shipment_id FROM photos WHERE id IN ({placeholders})", tuple(all_photo_ids)).fetchall()
        if len(rows) != len(all_photo_ids) or any(row["shipment_id"] for row in rows):
            raise HTTPException(status_code=400, detail="Одна или несколько фотографий недоступны")
        reference = _reference(conn)
        conn.execute(
            """INSERT INTO shipments(
                 id,reference,tracking_token_hash,status,delivery_mode,tariff,origin_json,destination_json,cargo_json,
                 client_name,client_phone,client_email,product_photo_ids_json,packaging_photo_ids_json,created_at,updated_at
               ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                shipment_id, reference, token_digest(token), "submitted", payload.delivery_mode.value, payload.tariff.value,
                dumps(payload.origin.model_dump()), dumps(payload.destination.model_dump()), dumps(payload.cargo.model_dump()),
                payload.client_name, payload.client_phone, payload.client_email,
                dumps(payload.product_photo_ids), dumps(payload.packaging_photo_ids), now, now,
            ),
        )
        for photo_id in payload.product_photo_ids:
            conn.execute("UPDATE photos SET shipment_id=?, kind='product' WHERE id=?", (shipment_id, photo_id))
        for photo_id in payload.packaging_photo_ids:
            conn.execute("UPDATE photos SET shipment_id=?, kind='packaging' WHERE id=?", (shipment_id, photo_id))
        conn.execute(
            "INSERT INTO status_events(id,shipment_id,from_status,to_status,actor_role,note,created_at) VALUES(?,?,?,?,?,?,?)",
            (str(uuid.uuid4()), shipment_id, None, "submitted", "client", "Клиент создал заявку", now),
        )
        conn.execute(
            "INSERT INTO audit_log(id,actor_role,action,entity_type,entity_id,data_json,created_at) VALUES(?,?,?,?,?,?,?)",
            (str(uuid.uuid4()), "client", "shipment.created", "shipment", shipment_id, dumps({"reference": reference}), now),
        )
    return get_shipment_detail(db, shipment_id), token


def hydrate_shipment(row: dict[str, Any], include_private: bool = True) -> dict[str, Any]:
    result = {
        "id": row["id"], "reference": row["reference"], "status": row["status"],
        "delivery_mode": row["delivery_mode"], "tariff": row["tariff"],
        "origin": loads(row["origin_json"], {}), "destination": loads(row["destination_json"], {}),
        "cargo": loads(row["cargo_json"], {}),
        "product_photo_ids": loads(row["product_photo_ids_json"], []),
        "packaging_photo_ids": loads(row["packaging_photo_ids_json"], []),
        "selected_route_id": row["selected_route_id"], "cargo_passport_id": row["cargo_passport_id"],
        "quote_id": row["quote_id"], "created_at": row["created_at"], "updated_at": row["updated_at"],
    }
    if include_private:
        result.update(client_name=row["client_name"], client_phone=row["client_phone"], client_email=row["client_email"])
    return result


def get_shipment_detail(db: DatabaseBackend, shipment_id: str, include_private: bool = True) -> dict[str, Any]:
    row = db.fetch_one("SELECT * FROM shipments WHERE id=?", (shipment_id,))
    if not row:
        raise HTTPException(status_code=404, detail="Заявка не найдена")
    result = hydrate_shipment(row, include_private)
    passport = db.fetch_one("SELECT data_json, confidence FROM cargo_passports WHERE shipment_id=?", (shipment_id,))
    result["cargo_passport"] = {**loads(passport["data_json"], {}), "confidence": passport["confidence"]} if passport else None
    result["agent_runs"] = [
        {**{k: v for k, v in item.items() if not k.endswith("_json")},
         "input": loads(item["input_json"], {}), "output": loads(item["output_json"], {}),
         "warnings": loads(item["warnings_json"], []), "errors": loads(item["errors_json"], [])}
        for item in db.fetch_all("SELECT * FROM agent_runs WHERE shipment_id=? ORDER BY started_at", (shipment_id,))
    ]
    result["routes"] = [loads(item["data_json"], {}) for item in db.fetch_all("SELECT data_json FROM routes WHERE shipment_id=? ORDER BY created_at", (shipment_id,))]
    bundles = db.fetch_all("SELECT * FROM quote_bundles WHERE shipment_id=? ORDER BY version DESC", (shipment_id,))
    for bundle in bundles:
        bundle["options"] = [
            {
                **{k: v for k, v in option.items() if include_private or k != "source_reference"},
                "recommended": bool(option["recommended"]),
            }
            for option in db.fetch_all(
                """SELECT * FROM quote_options WHERE bundle_id=?
                   ORDER BY CASE tariff WHEN 'flex' THEN 1 WHEN 'standard' THEN 2 WHEN 'priority' THEN 3 ELSE 4 END""",
                (bundle["id"],),
            )
        ]
        if not include_private:
            bundle.pop("approved_by", None)
    result["quote_bundles"] = bundles
    result["events"] = db.fetch_all("SELECT * FROM status_events WHERE shipment_id=? ORDER BY created_at", (shipment_id,))
    result["exceptions"] = db.fetch_all("SELECT * FROM exceptions WHERE shipment_id=? ORDER BY created_at DESC", (shipment_id,))
    return result


def authorize_client(db: DatabaseBackend, reference: str, token: str) -> dict[str, Any]:
    row = db.fetch_one("SELECT * FROM shipments WHERE reference=?", (reference.strip().upper(),))
    if not row or not verify_tracking_token(token, row["tracking_token_hash"]):
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Заявка не найдена или ссылка недействительна")
    return row


def photo_object(db: DatabaseBackend, storage: EvidenceStorage, photo_id: str, shipment_id: str | None = None) -> EvidenceObject:
    sql = "SELECT storage_path, mime_type FROM photos WHERE id=?"
    params: tuple[Any, ...] = (photo_id,)
    if shipment_id:
        sql += " AND shipment_id=?"
        params = (photo_id, shipment_id)
    row = db.fetch_one(sql, params)
    if not row:
        raise HTTPException(status_code=404, detail="Файл не найден")
    try:
        stored = storage.get(row["storage_path"], row["mime_type"])
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=503, detail="Хранилище фотографий временно недоступно") from exc
    if stored is None:
        raise HTTPException(status_code=404, detail="Файл отсутствует в хранилище")
    return stored


def add_capacity_offer(db: DatabaseBackend, payload: CapacityOfferCreate, created_by: str = "operator") -> dict[str, Any]:
    offer_id = str(uuid.uuid4())
    now = now_iso()
    db.execute(
        """INSERT INTO capacity_offers(
             id,carrier,flight,departure,destination,departure_at,cutoff_at,available_kg,available_m3,
             rate_per_kg,minimum_charge,currency,allowed_categories_json,restrictions_json,valid_until,
             source_reference,confidence,created_by,created_at
           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            offer_id, payload.carrier, payload.flight, payload.departure.upper(), payload.destination.upper(),
            payload.departure_at, payload.cutoff_at, payload.available_kg, payload.available_m3,
            payload.rate_per_kg, payload.minimum_charge, payload.currency,
            dumps(payload.allowed_categories), dumps(payload.restrictions), payload.valid_until,
            payload.source_reference, payload.confidence, created_by, now,
        ),
    )
    return db.fetch_one("SELECT * FROM capacity_offers WHERE id=?", (offer_id,)) or {}

