from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

import httpx

from .config import Settings


@dataclass(frozen=True)
class EvidenceObject:
    content: bytes
    mime_type: str


class LocalEvidenceStorage:
    def __init__(self, root: Path):
        self.root = root

    def put(self, object_name: str, content: bytes, mime_type: str) -> None:
        path = self.root / object_name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)

    def get(self, object_name: str, mime_type: str) -> EvidenceObject | None:
        path = self.root / object_name
        if not path.is_file():
            return None
        return EvidenceObject(path.read_bytes(), mime_type)

    def delete(self, object_name: str) -> None:
        path = self.root / object_name
        if path.is_file():
            path.unlink()


class SupabaseEvidenceStorage:
    """Server-only access to the private cargo-evidence bucket."""

    bucket = "cargo-evidence"

    def __init__(self, url: str, secret_key: str, transport: httpx.BaseTransport | None = None):
        self.base_url = f"{url.rstrip('/')}/storage/v1/object/{self.bucket}"
        self.headers = {"apikey": secret_key}
        if not secret_key.startswith("sb_secret_"):
            self.headers["Authorization"] = f"Bearer {secret_key}"
        self.transport = transport

    def put(self, object_name: str, content: bytes, mime_type: str) -> None:
        with httpx.Client(timeout=30, transport=self.transport) as client:
            response = client.post(
                f"{self.base_url}/{object_name}",
                headers={**self.headers, "Content-Type": mime_type, "x-upsert": "false"},
                content=content,
            )
        response.raise_for_status()

    def get(self, object_name: str, mime_type: str) -> EvidenceObject | None:
        with httpx.Client(timeout=30, transport=self.transport) as client:
            response = client.get(f"{self.base_url}/{object_name}", headers=self.headers)
        if response.status_code == 404:
            return None
        response.raise_for_status()
        return EvidenceObject(response.content, response.headers.get("content-type", mime_type))

    def delete(self, object_name: str) -> None:
        with httpx.Client(timeout=30, transport=self.transport) as client:
            response = client.request(
                "DELETE",
                f"{self.base_url}",
                headers={**self.headers, "Content-Type": "application/json"},
                json={"prefixes": [object_name]},
            )
        if response.status_code not in {200, 404}:
            response.raise_for_status()


EvidenceStorage = LocalEvidenceStorage | SupabaseEvidenceStorage


def create_storage(config: Settings) -> EvidenceStorage:
    if config.backend("storage") == "supabase":
        return SupabaseEvidenceStorage(config.supabase_url, config.supabase_secret_key)
    return LocalEvidenceStorage(config.uploads_dir)
